//! Characterization snapshots: every example under `examples/`, generated by the `isoloom` binary
//! on every target, one snapshot per example × target (`snapshots/examples/<example>__<target>.snap`).
//!
//! They freeze what `generate` writes today, so a change to the output is always deliberate and
//! reviewed (`cargo insta test --review`). A generated target's snapshot holds the target's line
//! from `isoloom targets`, what `generate --target` printed, then every file it wrote, sorted by
//! path, each under a `## <path>` header. A refused target's snapshot holds the refusal: the
//! `isoloom targets` reason and `generate`'s message.
//!
//! Each run copies the example, without any generated `.isoloom/` outputs, into a fresh folder,
//! and runs the binary with an empty `ISOLOOM_HOME` and no other `ISOLOOM_*` variable, so the
//! user's defaults and profile never leak in. A file a target shares with an earlier target of the
//! same example (`resolved.json` everywhere), byte for byte,
//! is written once, in the earlier snapshot; the later one names it and says where it is.

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::{Path, PathBuf};

use isoloom_spec::Target;

use crate::testing::{Run, isoloom};

/// What a project folder holds: each file's path (with `/`, relative to the folder) and bytes.
type Tree = BTreeMap<String, Vec<u8>>;

/// A step's outcome: a failure is the test's report (it crosses the examples' threads).
type Outcome<T = ()> = Result<T, Box<dyn std::error::Error + Send + Sync>>;

/// The folders an example may hold that aren't the project: generated outputs and tool state.
fn skipped(name: &str) -> bool {
    name == ".isoloom" || name.starts_with(".isoloom-") || name == ".vagrant" || name == ".terraform"
}

/// Every file under `dir`; with `projects_only`, without the skipped folders.
fn read_tree(dir: &Path, projects_only: bool) -> Outcome<Tree> {
    let mut tree = Tree::new();
    let mut stack = vec![(dir.to_path_buf(), String::new())];
    while let Some((at, prefix)) = stack.pop() {
        for entry in std::fs::read_dir(&at)? {
            let entry = entry?;
            let name = entry.file_name().to_string_lossy().into_owned();
            let rel = if prefix.is_empty() { name.clone() } else { format!("{prefix}/{name}") };
            if !entry.file_type()?.is_dir() {
                tree.insert(rel, std::fs::read(entry.path())?);
            } else if !(projects_only && skipped(&name)) {
                stack.push((entry.path(), rel));
            }
        }
    }
    Ok(tree)
}

/// Writes `tree` under `dir`.
fn write_tree(dir: &Path, tree: &Tree) -> Outcome {
    for (rel, bytes) in tree {
        let path = dir.join(rel);
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }
        std::fs::write(path, bytes)?;
    }
    Ok(())
}

/// What a command printed, stdout then stderr, with `dir` and `home` named, not spelled out.
fn printed(o: &Run, dir: &Path, home: &Path) -> String {
    normalize(&format!("{}{}", o.stdout, o.stderr), dir, home)
}

/// `text` with the run's folders as placeholders and LF line endings, so it reads the same on
/// every host. A folder's canonical path goes first: the temp folder's can be longer (macOS's
/// `/private/var/...` for `/var/...`).
fn normalize(text: &str, dir: &Path, home: &Path) -> String {
    let mut text = text.replace("\r\n", "\n");
    for (path, placeholder) in [(dir, "<project>"), (home, "<home>")] {
        if let Ok(canonical) = path.canonicalize() {
            text = text.replace(&canonical.display().to_string(), placeholder);
        }
        text = text.replace(&path.display().to_string(), placeholder);
    }
    // A release changes the generator's version, not the files: the 142 snapshots that held
    // the version broke at every release (a release's gate).
    text.replace(&format!("\"version\": \"{}\"", env!("CARGO_PKG_VERSION")), "\"version\": \"[version]\"")
}

/// The target's block in `isoloom targets`: its `✓`/`✗` line, and the lines indented under it
/// (the clouds `cloud-vm` refuses).
fn target_block(listing: &str, id: &str) -> Outcome<String> {
    let mut block = String::new();
    let mut inside = false;
    for line in listing.lines() {
        if let Some(rest) = line.strip_prefix("✓ ").or_else(|| line.strip_prefix("✗ ")) {
            inside = rest.split(' ').next() == Some(id);
        } else if !line.starts_with("    ") {
            inside = false;
        }
        if inside {
            block.push_str(line);
            block.push('\n');
        }
    }
    if block.is_empty() {
        return Err(format!("`isoloom targets` doesn't list {id}:\n{listing}").into());
    }
    Ok(block)
}

/// A file's contents as the snapshot shows them: its text, or a fingerprint of its bytes.
fn shown(bytes: &[u8], dir: &Path, home: &Path) -> String {
    std::str::from_utf8(bytes).map_or_else(|_| fingerprint(bytes), |text| decoded(&normalize(text, dir, home)))
}

/// `text` with each gzip-and-base64 value (a cloud-init file's `content`) written as what it
/// holds: the value becomes `<gzip N>`, and value N's decoded text follows the file. A deflate
/// library writes other bytes for the same payload from one version to the next; the snapshot
/// follows the payload, and isoloom-render's own test pins the compressed bytes once.
fn decoded(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut payloads = Vec::new();
    let mut rest = text;
    while let Some(at) = rest.find("\"H4sI") {
        let (before, value) = rest.split_at(at + 1);
        let end = value.find('"').unwrap_or(value.len());
        let (encoded, after) = value.split_at(end);
        out.push_str(before);
        if let Some(payload) = gunzip_base64(encoded) {
            payloads.push(payload);
            out.push_str(&["<gzip ", &payloads.len().to_string(), ">"].concat());
        } else {
            out.push_str(encoded);
        }
        rest = after;
    }
    out.push_str(rest);
    for (n, payload) in payloads.iter().enumerate() {
        out.push_str(&["### <gzip ", &(n + 1).to_string(), "> decoded\n", payload].concat());
        if !payload.ends_with('\n') {
            out.push('\n');
        }
    }
    out
}

/// The text gzip-compressed and base64-encoded in `encoded`, or `None` when it isn't that.
fn gunzip_base64(encoded: &str) -> Option<String> {
    use std::io::Read as _;
    let bytes = isoloom_test_support::b64_decode(encoded)?;
    let mut text = String::new();
    flate2::read::GzDecoder::new(bytes.as_slice()).read_to_string(&mut text).ok()?;
    Some(text)
}

/// [`isoloom`] across the examples' threads: its error as text, which crosses them.
fn run(home: &Path, args: &[&dyn AsRef<std::ffi::OsStr>]) -> Outcome<Run> {
    isoloom(home, args).map_err(|e| e.to_string().into())
}

/// A binary file as the snapshot shows it: its size and FNV-1a hash (stable, no dependency).
fn fingerprint(bytes: &[u8]) -> String {
    let hash = bytes
        .iter()
        .fold(0xcbf2_9ce4_8422_2325_u64, |h, b| (h ^ u64::from(*b)).wrapping_mul(0x0100_0000_01b3));
    format!("({} bytes, not UTF-8, FNV-1a {hash:016x})\n", bytes.len())
}

/// One example, generated on every target: the snapshots, in `Target::ALL` order.
struct Example {
    name: String,
    snapshots: Vec<(Target, String)>,
}

/// The files of one example already written into an earlier target's snapshot: path, then the
/// bytes and the target whose snapshot holds them.
type Seen = BTreeMap<String, (Vec<u8>, Target)>;

/// The snapshot of one target: the example (its files, `source`) generated in a fresh copy under
/// `work`. `listing` is what `isoloom targets` printed for it.
fn snapshot(work: &Path, source: &Tree, listing: &str, target: Target, seen: &mut Seen) -> Outcome<String> {
    let dir = work.join(target.id());
    let home = work.join(format!("home-{}", target.id()));
    write_tree(&dir, source)?;
    std::fs::create_dir_all(&home)?;
    let o = run(&home, &[&"generate", &dir, &"--target", &target.id()])?;
    let code = o.code.map_or_else(|| "signal".to_owned(), |c| c.to_string());
    let mut out = String::new();
    writeln!(out, "# isoloom targets\n{}", target_block(listing, target.id())?)?;
    writeln!(out, "# isoloom generate --target {} (exit {code})\n{}", target.id(), printed(&o, &dir, &home))?;
    let written: Tree = read_tree(&dir, false)?
        .into_iter()
        .filter(|(rel, bytes)| source.get(rel) != Some(bytes))
        .collect();
    for (rel, bytes) in written {
        match seen.get(&rel) {
            Some((before, owner)) if *before == bytes => {
                writeln!(out, "## {rel}: identical in the `{}` snapshot\n", owner.id())?;
            }
            _ => {
                writeln!(out, "## {rel}\n{}", shown(&bytes, &dir, &home))?;
                seen.insert(rel, (bytes, target));
            }
        }
    }
    Ok(out)
}

/// Every target's snapshot for the example in `dir`, generated under `work`.
fn generate_example(dir: &Path, work: &Path) -> Outcome<Example> {
    let name = dir.file_name().ok_or("an example with no name")?.to_string_lossy().into_owned();
    let source = read_tree(dir, true)?;
    let listed = work.join("listed");
    let home = work.join("home-listed");
    write_tree(&listed, &source)?;
    std::fs::create_dir_all(&home)?;
    let o = run(&home, &[&"targets", &listed])?;
    let listing = printed(&o, &listed, &home);
    if o.code != Some(0) {
        return Err(format!("{name}: `isoloom targets` failed:\n{listing}").into());
    }
    let mut seen = Seen::new();
    let snapshots = Target::ALL
        .into_iter()
        .map(|t| Ok((t, snapshot(work, &source, &listing, t, &mut seen)?)))
        .collect::<Outcome<Vec<_>>>()?;
    Ok(Example { name, snapshots })
}

/// The example folders, by name.
fn examples() -> Outcome<Vec<PathBuf>> {
    let root = crate::testing::example("");
    let mut dirs = Vec::new();
    for entry in std::fs::read_dir(&root)? {
        let path = entry?.path();
        if path.join("isoloom.yml").is_file() {
            dirs.push(path);
        }
    }
    dirs.sort();
    Ok(dirs)
}

#[test]
fn every_example_on_every_target_is_its_snapshot() -> Outcome {
    let scratch = tempfile::Builder::new().prefix("isoloom-example-snapshots-").tempdir()?;
    let dirs = examples()?;
    assert!(!dirs.is_empty(), "no example found");
    // The examples in batches of as many threads as the host has cores (each runs the binary
    // once per target): one thread per example would be a fan-out the host couldn't bound, on top
    // of the test runner's own parallelism; `ISOLOOM_TEST_JOBS` caps
    // it lower on a shared host. Snapshots are asserted in order afterwards.
    let jobs = std::env::var("ISOLOOM_TEST_JOBS")
        .ok()
        .and_then(|j| j.parse::<usize>().ok())
        .filter(|j| *j > 0)
        .unwrap_or_else(|| std::thread::available_parallelism().map_or(4, std::num::NonZeroUsize::get));
    let mut generated: Vec<Example> = Vec::with_capacity(dirs.len());
    for batch in dirs.chunks(jobs) {
        let done: Vec<Example> = std::thread::scope(|s| {
            let handles: Vec<_> = batch
                .iter()
                .map(|dir| {
                    let work = scratch.path().join(dir.file_name().unwrap_or_default());
                    s.spawn(move || generate_example(dir, &work))
                })
                .collect();
            handles
                .into_iter()
                .map(|h| h.join().map_err(|_| "an example's thread panicked")?)
                .collect::<Outcome<Vec<_>>>()
        })?;
        generated.extend(done);
    }
    drop(scratch);
    let mut settings = insta::Settings::clone_current();
    settings.set_snapshot_path("snapshots/examples");
    settings.set_prepend_module_to_snapshot(false);
    settings.set_omit_expression(true);
    settings.bind(|| {
        for example in &generated {
            for (target, contents) in &example.snapshots {
                insta::assert_snapshot!(format!("{}__{}", example.name, target.id()), contents);
            }
        }
    });
    // Every snapshot of the folder is one this test asserts: one left by a removed example or
    // target would never fail again.
    let asserted: std::collections::BTreeSet<String> = generated
        .iter()
        .flat_map(|e| e.snapshots.iter().map(move |(target, _)| format!("{}__{}.snap", e.name, target.id())))
        .collect();
    let folder = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/cli/snapshots/examples");
    let mut unreferenced: Vec<String> = std::fs::read_dir(&folder)?
        .filter_map(Result::ok)
        .map(|e| e.file_name().to_string_lossy().into_owned())
        .filter(|name| Path::new(name).extension().is_some_and(|x| x == "snap") && !asserted.contains(name))
        .collect();
    unreferenced.sort();
    assert_eq!(unreferenced, Vec::<String>::new(), "snapshots no test asserts: remove them");
    Ok(())
}
